const fs = require("fs");
const path = require("path");
const ts = require("typescript");
// Bundle the same pure resolver used by React for the classic service worker.
const source = fs.readFileSync(
  path.join(__dirname, "../src/lib/notifications/notification-routing.ts"),
  "utf8",
);
const compiled = ts.transpileModule(source, {
  compilerOptions: {
    module: ts.ModuleKind.CommonJS,
    target: ts.ScriptTarget.ES2020,
  },
}).outputText;
fs.writeFileSync(
  path.join(__dirname, "../public/notification-routing.js"),
  "// Generated by scripts/inject-sw-version.js; edit the TypeScript source.\n" +
    "(function () { const exports = {};\n" +
    compiled +
    "\nself.yrdlyNotificationRouting = exports; })();\n",
);

const swPath = path.join(__dirname, "..", "public", "sw.js");

// Exit gracefully if sw.js doesn't exist (e.g. fresh clone without the file committed)
if (!fs.existsSync(swPath)) {
  console.warn(
    "inject-sw-version: sw.js not found at",
    swPath,
    "– skipping version injection",
  );
  process.exit(0);
}

// Use Vercel's commit SHA (short) so each deploy busts the cache; fallback to timestamp for local
const version =
  process.env.VERCEL_GIT_COMMIT_SHA?.slice(0, 7) ||
  process.env.NEXT_PUBLIC_VERCEL_GIT_COMMIT_SHA?.slice(0, 7) ||
  `local-${Date.now()}`;

let content = fs.readFileSync(swPath, "utf8");

// Match: const CACHE_VERSION = 'anything';
const regex = /const CACHE_VERSION = '.*';/;

if (!regex.test(content)) {
  console.warn(
    "inject-sw-version: CACHE_VERSION variable not found in sw.js, skipping",
  );
  process.exit(0);
}

content = content.replace(regex, `const CACHE_VERSION = '${version}';`);
fs.writeFileSync(swPath, content);
console.log("inject-sw-version: set cache version to", version);
